"""Pricing helpers."""

DISCOUNT_RATE = 0.15


def gross(net):
    return net * (1 + DISCOUNT_RATE)


def tax(net):
    return net * DISCOUNT_RATE


def label(net):
    return f"{net} plus {net * DISCOUNT_RATE:.2f}"


def version():
    return "0.15.0"
